function initRenderTelemetry(){const p=NQ.renderPerf;const loop=(ts)=>{if(p.last){const dt=ts-p.last;p.samples.push(dt);if(p.samples.length>240)p.samples.shift();p.frames++;if(dt>20)p.dropped++;if(p.frames%30===0&&p.samples.length){const a=p.samples.slice().sort((x,y)=>x-y),sum=p.samples.reduce((x,y)=>x+y,0);p.fps=sum>0?1000/(sum/p.samples.length):0;p.p95=a[Math.min(a.length-1,Math.floor(a.length*.95))]||0;const x=$('techRender');if(x){x.textContent=`${p.fps.toFixed(0)} FPS · ${p.p95.toFixed(1)}ms p95`;x.className=`tech-state ${p.fps>=90&&p.p95<=12?'ok':p.fps>=50?'ready':'warn'}`;x.title=`Browser render telemetry · dropped>${20}ms: ${p.dropped}/${p.frames}. 120 FPS capable depends on monitor/GPU/browser.`;}window.dispatchEvent(new CustomEvent('itmq:render-perf',{detail:{fps:p.fps,frame_p95_ms:p.p95,dropped_frames:p.dropped,total_frames:p.frames,backend:NQ.surfaceBackend}}));}}p.last=ts;requestAnimationFrame(loop);};requestAnimationFrame(loop);}

