function miniRender(id,spec){if(!spec||!window.ITMQUltraCharts?.render)return false;NQ.miniPending.set(id,spec);if(!NQ.miniTimer){const delay=window.ITMQLiveScheduler?.cadence?.('mini')??250;NQ.miniTimer=setTimeout(()=>{NQ.miniTimer=0;const batch=[...NQ.miniPending.entries()];NQ.miniPending.clear();for(const [chartId,chartSpec] of batch){try{window.ITMQUltraCharts.render(chartId,chartSpec);}catch(e){console.warn('[ITM QUANT MINI COALESCE]',chartId,e);}}},delay);}return true;}
function flowMiniSpecFromTrace(p){const pts=traceArray(p?.option_prints,'option_prints','TRACE_FLOW_DOCK');if(!pts.length)return null;const bins=new Map();for(const row of pts){const t=new Date(row.t).getTime();if(!Number.isFinite(t))continue;const k=Math.floor(t/60000)*60000,dir=num(row.direction,0),premium=Math.abs(num(row.premium,0)),b=bins.get(k)||{net:0,gross:0};b.net+=premium*(dir>0?1:dir<0?-1:0);b.gross+=premium;bins.set(k,b);}const rows=[...bins.entries()].sort((a,b)=>a[0]-b[0]).slice(-120);if(!rows.length)return null;const gross=rows.map(([,b])=>b.gross).sort((a,b)=>a-b),q85=gross[Math.min(gross.length-1,Math.floor((gross.length-1)*.85))]||Infinity,x=rows.map(([t])=>new Date(t).toISOString()),y=rows.map(([,b])=>b.net/1e6),colors=rows.map(([,b])=>b.gross>=q85&&rows.length>=4?'#f0c457':b.net>=0?'#36bf83':'#e05261');return{data:[{type:'bar',x,y,name:'OPRA NET $M',marker:{color:colors}}],layout:{showlegend:false,uirevision:`trace-flow-mini-${p?.symbol||'ASSET'}`,hovermode:'x unified',dragmode:'pan'}};}
function compactNetDriftMini(spec){const raw=traceArray(spec?.data,'net_drift.data','TRACE_FLOW_DOCK');if(!raw.length)return null;let data=raw.filter(t=>/CALL DRIFT|PUT DRIFT|NET DRIFT/i.test(String(t?.name||''))&&String(t?.type||'scatter').toLowerCase()==='scatter').slice(0,3);if(!data.length)data=raw.filter(t=>String(t?.type||'scatter').toLowerCase()==='scatter'&&!/PRICE/i.test(String(t?.name||''))).slice(0,3);if(!data.length)return null;data=data.map(t=>({...t,yaxis:'y',xaxis:'x'}));return{data,layout:{showlegend:true,uirevision:`${spec?.layout?.uirevision||'net-drift'}-trace-mini`,hovermode:'x unified',dragmode:'pan',meta:{...(spec?.layout?.meta||{}),bridge_session_gaps:true,provider:'QUANTDATA'}}};}
function updateDealerMini(p){const di=p?.dealer_intelligence||{},shift=num(di?.inventory_shift?.score,null),state=num(di?.dealer_state_score,null),t=new Date(p?.profiles?.asof||p?.profiles?.timestamp||Date.now()).getTime();if(!Number.isFinite(t)||(shift==null&&state==null))return;const last=NQ.dealerHistory[NQ.dealerHistory.length-1],rec={t,shift,state};if(last&&last.t===t)NQ.dealerHistory[NQ.dealerHistory.length-1]=rec;else NQ.dealerHistory.push(rec);if(NQ.dealerHistory.length>240)NQ.dealerHistory.splice(0,NQ.dealerHistory.length-240);const rows=NQ.dealerHistory.filter(r=>Number.isFinite(r.t));if(!rows.length)return;const data=[];if(rows.some(r=>r.shift!=null))data.push({type:'scatter',mode:'lines',name:'INVENTORY SHIFT',x:rows.map(r=>new Date(r.t).toISOString()),y:rows.map(r=>r.shift==null?NaN:r.shift),line:{color:'#f0c457',width:1.6}});if(rows.some(r=>r.state!=null))data.push({type:'scatter',mode:'lines',name:'DEALER STATE',x:rows.map(r=>new Date(r.t).toISOString()),y:rows.map(r=>r.state==null?NaN:r.state),line:{color:'#9a82e1',width:1.4}});if(data.length){miniRender('traceDealerMiniChart',{data,layout:{showlegend:true,uirevision:`trace-dealer-mini-${p?.symbol||'ASSET'}`,hovermode:'x unified',dragmode:'pan'}});miniSetStatus('traceDealerMiniState',`${rows.length} PULSES · EST.`,String(di?.state||'ESTIMATED'));}}
function updateTraceMiniDock(p){const flow=flowMiniSpecFromTrace(p),op=p?.opra_diagnostics||{},sym=String(p?.symbol||p?.profiles?.symbol||'ASSET').toUpperCase();if(flow){miniRender('traceFlowMiniChart',flow);const n=traceArray(p?.option_prints,'option_prints','TRACE_FLOW_DOCK').length;miniSetStatus('traceFlowMiniState',`${n} PRINTS · OPRA ${op.status||'LIVE'}`,'LIVE');}else{const st=String(op.status||'WAITING').replaceAll('_',' '),title=op.status==='LIVE'?'OPRA LIVE · 0 PRINTS':`OPRA ${st}`;miniRender('traceFlowMiniChart',miniEmptySpec(title,`No hay flujo inusual OPRA observado para ${sym} en la ventana activa. El panel aparecerá al llegar prints reales.`,`trace-flow-empty-${sym}`));miniSetStatus('traceFlowMiniState',title,'WAITING');}const beforeDealer=NQ.dealerHistory.length;updateDealerMini(p);if(!NQ.dealerHistory.length&&!beforeDealer){miniRender('traceDealerMiniChart',miniEmptySpec('DEALER · ESPERANDO PULSOS','Se necesitan snapshots cuantitativos sucesivos del mismo activo para dibujar inventario/dealer state.',`trace-dealer-empty-${sym}`));}if(NQ.lastNetDriftSpec){const drift=compactNetDriftMini(NQ.lastNetDriftSpec);if(drift){miniRender('traceDriftMiniChart',drift);miniSetStatus('traceDriftMiniState','SYNC · 15s','LIVE');}else{miniRender('traceDriftMiniChart',miniEmptySpec('NET DRIFT · SIN HISTORIAL SUFICIENTE','Se requieren snapshots estructurales reales; los huecos no se rellenan con datos sintéticos.',`trace-drift-empty-${sym}`));miniSetStatus('traceDriftMiniState','SIN HISTORIAL','WAITING');}}else{miniRender('traceDriftMiniChart',miniEmptySpec('NET DRIFT · ESPERANDO CHART','El histórico aparecerá cuando el backend entregue snapshots estructurales del activo.',`trace-drift-wait-${sym}`));}}
function setMiniSpecs(v={}){if(v.netDrift){NQ.lastNetDriftSpec=v.netDrift;const drift=compactNetDriftMini(v.netDrift);if(drift){miniRender('traceDriftMiniChart',drift);miniSetStatus('traceDriftMiniState','SYNC · CHART','LIVE');}else miniSetStatus('traceDriftMiniState','SIN HISTORIAL','WAITING');}}

function nySessionKey(symbol,tf){let day='';try{day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}catch(_){day=new Date().toISOString().slice(0,10);}return `${String(symbol||'ASSET').toUpperCase()}:${day}:${String(tf||'1m').toLowerCase()}`;}
async function ensureTraceBootstrap(tf,symbol,scope='full_day'){
 const sym=String(symbol||'ASSET').toUpperCase(),key=`${nySessionKey(sym,tf)}:${scope}`,now=Date.now();
 if(NQ.sessionBootstrapKey===key&&NQ.sessionBootstrap?.ready&&Date.now()-Number(NQ.sessionBootstrapAppliedAt||0)<8000)return NQ.sessionBootstrap;
 if(NQ.sessionBootstrapBusy&&NQ.sessionBootstrapKey===key)return NQ.sessionBootstrapBusy;
 if(NQ.sessionBootstrapKey===key&&now<NQ.sessionBootstrapRetryAt&&NQ.sessionBootstrap?.ready)return NQ.sessionBootstrap;
 NQ.sessionBootstrapKey=key;const requestKey=key;
 const apply=(p,phase)=>{
  if(NQ.sessionBootstrapKey!==requestKey||!p||String(p.symbol||'').toUpperCase()!==sym)return false;
  if(p.ready&&traceArray(p.bars,'bootstrap.bars',`ensureTraceBootstrap.${phase}`).length){
   NQ.sessionBootstrap=p;NQ.sessionBootstrapAppliedAt=Date.now();withActiveTrace(r=>r.setSessionBootstrap(p));NQ.sessionBootstrapRetryAt=0;return true;
  }
  // Failed refreshes update diagnostics but must not delete already visible history.
  withActiveTrace(r=>r.setSessionBootstrap(p));if(!NQ.sessionBootstrap?.ready)NQ.sessionBootstrap=p;return false;
 };
 NQ.sessionBootstrapBusy=(async()=>{
  let cached=null,provider=null;
  try{
   // Stage 1: disk-only continuity. This usually returns in milliseconds on restart.
   cached=await api(`/api/trace/session-bootstrap?timeframe=${encodeURIComponent(tf)}&symbol=${encodeURIComponent(sym)}&scope=${encodeURIComponent(scope)}&cache_only=true`);
   apply(cached,'cache');
  }catch(e){console.warn('TRACE CACHE BOOTSTRAP',sym,e);}
  try{
   // Stage 2: Alpaca refresh. It extends/replaces the cache with current observed bars.
   provider=await api(`/api/trace/session-bootstrap?timeframe=${encodeURIComponent(tf)}&symbol=${encodeURIComponent(sym)}&scope=${encodeURIComponent(scope)}&force=true&allow_display_fallback=true`);
   const ok=apply(provider,'provider');
   if(!ok&&NQ.sessionBootstrapKey===requestKey)NQ.sessionBootstrapRetryAt=Date.now()+3000;
  }catch(e){if(NQ.sessionBootstrapKey===requestKey)NQ.sessionBootstrapRetryAt=Date.now()+3000;console.warn('TRACE ALPACA BOOTSTRAP',sym,e);}
  return provider?.ready?provider:(cached?.ready?cached:provider||cached);
 })().finally(()=>{if(NQ.sessionBootstrapKey===requestKey)NQ.sessionBootstrapBusy=null;});
 return NQ.sessionBootstrapBusy;
}

