function prepareSymbolBootstrap(symbol,bootstrap,opts={}){const sym=String(symbol||'ASSET').toUpperCase();if(NQ.activeSymbol&&NQ.activeSymbol!==sym)return false;if(!bootstrap||String(bootstrap.symbol||'').toUpperCase()!==sym)return false;NQ.activeSymbol=sym;NQ.sessionBootstrap=bootstrap;NQ.sessionBootstrapKey=`${nySessionKey(sym,bootstrap.timeframe||$('traceCandle')?.value||'1m')}:${bootstrap.scope||'full_day'}`;withActiveTrace(r=>r.setSessionBootstrap(bootstrap));const last=traceArray(bootstrap.bars,'bootstrap.bars','prepareSymbolBootstrap').slice(-1)[0],spot=num(last?.c,null);if(!NQ.lastPayload||String(NQ.lastPayload.symbol||'').toUpperCase()!==sym){const provisional={ready:true,symbol:sym,timeframe:bootstrap.timeframe||'1m',tail_minutes:0,candles:[],option_prints:[],levels:[],profiles:{ready:false,symbol:sym,rows:[],spot,gamma_delta_interaction:{}},decision:{},market_state:{top_factors:[]},dealer_intelligence:{},quality:{},native_options_structure:{ready:false,status:'WAITING_QUANT',authority:'ITM_QUANT_NATIVE_OPTIONS_STRUCTURE',provider_dependency:'NONE'},itm_structural_flow:{ready:false,status:'WAITING_QUANT',series:[]},opra_diagnostics:{symbol:sym,status:'WAITING_QUANT',connected:false},visual:{price_grid_step:null}};withActiveTrace(r=>r.setPayload(provisional));}return true;}

